// Packs the files the program serves or writes into generated modules, so the bundle and the single executable carry
// them in memory: the web board's files (src/web → src/web/assets.generated.ts) and the templates init writes
// (templates → src/templates.generated.ts). Run by the test, typecheck and build scripts; generated files are not
// committed.
import { readFileSync, readdirSync, writeFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'

const dir = fileURLToPath(new URL('../src/web/', import.meta.url))
const TYPES = { '.html': 'text/html; charset=utf-8', '.css': 'text/css; charset=utf-8', '.js': 'text/javascript; charset=utf-8', '.svg': 'image/svg+xml' }
const assets = {}
for (const name of readdirSync(dir).sort()) {
  const ext = name.slice(name.lastIndexOf('.'))
  if (!TYPES[ext] || name.endsWith('.generated.ts')) continue
  assets[`/${name}`] = { type: TYPES[ext], body: readFileSync(dir + name, 'utf8') }
}
writeFileSync(
  `${dir}assets.generated.ts`,
  `// Generated by scripts/web-assets.mjs from the files beside it. Do not edit.\nexport const ASSETS: Record<string, { type: string; body: string }> = ${JSON.stringify(assets, null, 1)}\n`,
)

const templates = fileURLToPath(new URL('../templates/', import.meta.url))
const texts = {}
for (const name of readdirSync(templates).sort()) texts[name] = readFileSync(templates + name, 'utf8').replace(/\r\n/g, '\n')
writeFileSync(
  fileURLToPath(new URL('../src/templates.generated.ts', import.meta.url)),
  `// Generated by scripts/web-assets.mjs from core/templates. Do not edit.\nexport const TEMPLATES: Record<string, string> = ${JSON.stringify(texts, null, 1)}\n`,
)
